let ru = Set(ruExtra).union(ShortWords.ru).sorted()
let en = Set(enExtra).union(ShortWords.en).sorted()
func row(_ kind: String,_ lang: Lang,_ expected: String,_ input: String) {
 var answers:[String] = []
 for seed in ["","привет","hello"] { let d=Detector(); if !seed.isEmpty { _ = d.verdict(for:seed) }; answers.append(String(describing:d.verdict(for:input))) }
 print([kind,lang == .ru ? "ru":"en",expected,input]+answers, separator: "")
}
func emit(_ kind: String,_ lang: Lang,_ expected: String,_ input: String) {
 var answers:[String] = []
 for seed in ["","привет","hello"] { let d=Detector(); if !seed.isEmpty { _ = d.verdict(for:seed) }; answers.append(String(describing:d.verdict(for:input))) }
 print(([kind,lang == .ru ? "ru":"en",expected,input]+answers).joined(separator:"\t"))
}
